const telegramWorkJoin = `-- name: TelegramWorkJoin :execrows
UPDATE telegram_work SET session_id = $1, last_at = clock_timestamp() WHERE id = $2 AND closed_at IS NULL
`

type TelegramWorkJoinParams struct {
	SessionID string
	ID        string
}

// A work item moves to another conversation (join): later messages go there.
func (q *Queries) TelegramWorkJoin(ctx context.Context, arg TelegramWorkJoinParams) (int64, error) {
	result, err := q.db.Exec(ctx, telegramWorkJoin, arg.SessionID, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const telegramWorkLastReply = `-- name: TelegramWorkLastReply :one
SELECT text, created_at FROM telegram_outbox WHERE work_id = $1 AND id LIKE 'reply:%' ORDER BY created_at DESC LIMIT 1
`

type TelegramWorkLastReplyRow struct {
	Text      string
	CreatedAt time.Time
}

// The newest answer Fleet sent for a work item, for the conductor's context.
func (q *Queries) TelegramWorkLastReply(ctx context.Context, workID *string) (TelegramWorkLastReplyRow, error) {
	row := q.db.QueryRow(ctx, telegramWorkLastReply, workID)
	var i TelegramWorkLastReplyRow
	err := row.Scan(&i.Text, &i.CreatedAt)
	return i, err
}

const telegramWorkList = `-- name: TelegramWorkList :many
SELECT id, room_id, session_id, title, created_by, created_at, last_at, closed_at FROM telegram_work WHERE closed_at IS NULL ORDER BY last_at DESC LIMIT 500
`

func (q *Queries) TelegramWorkList(ctx context.Context) ([]TelegramWork, error) {
	rows, err := q.db.Query(ctx, telegramWorkList)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []TelegramWork
	for rows.Next() {
		var i TelegramWork
		if err := rows.Scan(
			&i.ID,
			&i.RoomID,
			&i.SessionID,
			&i.Title,
			&i.CreatedBy,
			&i.CreatedAt,
			&i.LastAt,
			&i.ClosedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const telegramWorkLock = `-- name: TelegramWorkLock :exec
SELECT id FROM telegram_work WHERE id = $1 FOR UPDATE
`

// Serialises the reply steps of one work item, so the last one to end sees the others gone and writes the status.
func (q *Queries) TelegramWorkLock(ctx context.Context, id string) error {
	_, err := q.db.Exec(ctx, telegramWorkLock, id)
	return err
}

